    size_t maxlen = args->maxlen;
    streamID *id = &args->minid;
    int approx = args->approx_trim;
    int64_t limit = args->limit;
    int trim_strategy = args->trim_strategy;

    if (trim_strategy == TRIM_STRATEGY_NONE || rt->numele == 0)
        return 0;

    raxIterator ri;
    raxStart(&ri,rt);
    raxSeek(&ri,"^",NULL,0);

    int64_t deleted = 0;
    while (raxNext(&ri)) {
        if (trim_strategy == TRIM_STRATEGY_MAXLEN && s->length <= maxlen)
            break;

        unsigned char *lp = ri.data, *p = lpFirst(lp);
        listpackEntry header_entry;
        unsigned int header_slen;
        unsigned char *header_str = lpGetValue(p, &header_slen, &header_entry.lval);
        int64_t entries;
        if (header_str == NULL) {
            entries = header_entry.lval;
        } else {
            long long header_ll;
            int header_ret = string2ll((char*)header_str, header_slen, &header_ll);
            serverAssert(header_ret != 0);
            entries = header_ll;
        }

        /* Check if we exceeded the amount of work we could do */
        if (limit && (deleted + entries) > limit)
            break;

        /* Check if we can remove the whole node. */
        int remove_node;
        streamID master_id = {0}; /* For MINID */
        if (trim_strategy == TRIM_STRATEGY_MAXLEN) {
            remove_node = s->length - entries >= maxlen;
        } else {
            /* Read the master ID from the radix tree key. */
            streamDecodeID(ri.key, &master_id);

            /* Read last ID. */
